using System.Collections.Generic;
using UnityEngine;

public partial class FullMapOverlay {
 public sealed class Place {public string name,description,capabilityLabel;public Vector3 position;public MapStop approach;public int glyph;public bool roadPoint;}
 public sealed class PaintedSegment {public Vector3 a,b;public Color color;public bool passenger;}
 public readonly List<PaintedSegment> RoutePaint=new List<PaintedSegment>();
 List<Place> cachedPlaces;MapData placesMap;float nextPlaces;
 public JobOffer PreviewOffer {get{return selectedOffer;}}
 List<Vector3> pickupPath=new List<Vector3>(),ridePath=new List<Vector3>();JobOffer cachedRide;
 public int PickupPreviewPointCount {get{return pickupPath.Count;}}
 public void ShowCalls(){if(session.jobs.Active&&RestoreTripRoute())return;selectedPlace=null;if(selectedOffer!=null&&SelectedOffer>=0&&!session.jobs.Active)SelectOffer(SelectedOffer);else {previewPath.Clear();RefreshRoutePaint(true);}}
 List<Vector3> previewPath=new List<Vector3>();Place selectedPlace;float nextPaint;
 public int PreviewPointCount {get{return previewPath.Count;}}
 public string SelectedPlaceName {get{return selectedPlace==null?"":selectedPlace.name;}}
 public int[] ActiveStopPins {get{var jobs=session.jobs;if(!jobs.Active||jobs.current==null)return new int[0];return jobs.PassengerViaPending?new[]{jobs.current.pickup,jobs.current.drop,jobs.PassengerViaStop}:new[]{jobs.current.pickup,jobs.current.drop};}}
 public bool RestoreTripRoute(bool resumePickup=true){var jobs=session.jobs;if(!IsOpen||!jobs.Active||jobs.current==null)return false;if(resumePickup&&jobs.trip.State==TripState.ToPickup){jobs.ResumePickupNavigation();session.services.destination="";}selectedPlace=null;selectedOffer=null;SelectedOffer=-1;acceptFeedback="";previewPath.Clear();RefreshRoutePaint(true);if(jobs.trip.State==TripState.ToPickup)FitRoutes(jobs.nav.path,ridePath);else FitRoutes(jobs.nav.path);return true;}
 public List<Place> Places(){
  var map=session.world.map;if(cachedPlaces!=null&&placesMap==map&&Time.unscaledTime<nextPlaces)return cachedPlaces;placesMap=map;nextPlaces=Time.unscaledTime+1;var result=new List<Place>();
  foreach(var station in session.services.Stations)result.Add(new Place{name=station.name+" · "+station.ServiceLabel,capabilityLabel=station.ServiceLabel,position=station.pump,approach=station.approach,glyph=8,description=station.ServiceLabel+"\n입구로 진입해 주유 구역에 정차 후 F7\n연료를 최대 10%씩 추가합니다.\n"+session.services.Quote(0)+(station.SupportsWash?"\n\n"+session.services.Quote(4):"")});
  if(ProjectMapScene.Active(map)){foreach(var o in map.projectScene.objects)if(o.enabled&&o.IsService)result.Add(ServicePlace(o.name,o.Position,ProjectMapScene.ServiceStop(map,o),o.kind));}
  else {if(session.services.HasService(1))result.Add(ServicePlace("기사 식당",session.services.MealPosition,session.services.MealStop,"restaurant"));if(session.services.HasService(2))result.Add(ServicePlace("주차장",session.services.ParkingStop.V(),session.services.StopFor(2),"parking"));var r=session.services.RestArea;if(r!=null)result.Add(ServicePlace("휴식 주차",r.pump,r.approach,"rest"));}
  cachedPlaces=result;return result;
 }
 Place ServicePlace(string name,Vector3 p,MapStop stop,string kind){return new Place{name=name,position=p,approach=stop,glyph=kind=="restaurant"?9:kind=="rest"?11:10,description=kind=="restaurant"?"기사 식당\n제육백반 / 된장찌개 정식 / 소고기국밥\n각 3,000원 · 식사 50초 · 포만감 +70\n입구로 진입해 식당 앞 주차 칸에 정차 후 F7":kind=="rest"?"휴식 주차 구역\n무료 수면 · 100초\n주차 구역에 정차 후 F7":"생활 거점 주차장\n차량을 주차한 뒤 F7\n휴식 또는 하루 영업을 마칠 수 있습니다."};}
 public bool SelectPlace(Place place){if(!IsOpen||place==null||place.approach==null&&!place.roadPoint)return false;selectedPlace=place;selectedOffer=null;SelectedOffer=-1;acceptFeedback="";previewPath=place.roadPoint?session.jobs.nav.PreviewPoint(place.position):session.jobs.nav.PreviewTo(place.approach);FitRoutes(previewPath);RefreshRoutePaint(true);return true;}
 public bool SelectRoadPoint(Vector3 point){if(!IsOpen)return false;var path=session.jobs.nav.PreviewPoint(point);if(path.Count<2)return false;var end=path[path.Count-1];MapStop stop=null;var graph=session.jobs.nav.hd;if(graph!=null){float at;int edge=graph.Nearest(end,end-path[path.Count-2],out at);var dir=graph.paths[edge].Tangent(at);stop=new MapStop{name="지도 목적지",x=end.x,z=end.z,dx=dir.x,dz=dir.z,graphStop=true,laneEdge=edge,laneAt=at};}return SelectPlace(new Place{name="선택한 도로 지점",position=end,approach=stop,glyph=3,roadPoint=stop==null,description="선택 위치 인근의 연결된 차로까지 안내합니다.\n정차 허용 장소를 뜻하지 않습니다. 주변 표지와 도로 상황을 확인하세요."});}

 bool SelectedPickupFuel {get{return selectedPlace!=null&&selectedPlace.glyph==8&&session.jobs.trip.State==TripState.ToPickup;}}
 public bool StartPlaceGuidance(){if(!IsOpen||previousPause||selectedPlace==null||previewPath.Count<2||session.jobs.Active&&!SelectedPickupFuel)return false;var place=selectedPlace;Close();if(place.roadPoint)session.jobs.nav.SetDestination(place.position);else session.jobs.nav.SetDestination(place.approach);session.services.destination=place.name+" · 입구 앞까지 길안내";selectedPlace=null;previewPath.Clear();RefreshRoutePaint(true);return true;}
 public static Color CongestionColor(float delay){return delay>=6?new Color(.95f,.18f,.15f):delay>=2?new Color(1,.65f,.05f):new Color(.15f,.85f,.4f);}
 public void FitRoutes(params List<Vector3>[] paths){float minX=float.MaxValue,minZ=float.MaxValue,maxX=float.MinValue,maxZ=float.MinValue;foreach(var path in paths)foreach(var p in path){minX=Mathf.Min(minX,p.x);maxX=Mathf.Max(maxX,p.x);minZ=Mathf.Min(minZ,p.z);maxZ=Mathf.Max(maxZ,p.z);}if(minX==float.MaxValue)return;float span=Mathf.Max(session.world.map.width,session.world.map.depth);center=new Vector2(.5f+((minX+maxX)/2-session.world.map.width/2)/span,.5f-((minZ+maxZ)/2-session.world.map.depth/2)/span);ZoomLevel=Mathf.Clamp(span/(Mathf.Max(maxX-minX,maxZ-minZ)+160),1,8);ClampCenter();}
 void PaintPath(List<Vector3> path,bool passenger){float traveled=0;for(int i=1;i<path.Count;i++){var a=path[i-1];var b=path[i];float length=Vector3.Distance(a,b);if(length<.001f)continue;float delay=session.roadConditions==null?0:session.roadConditions.ExtraSeconds(a,b,(b-a).normalized,3.2f);var color=CongestionColor(delay);if(!passenger)RoutePaint.Add(new PaintedSegment{a=a,b=b,color=color});else {float d=0;while(d<length){float phase=Mathf.Repeat(traveled+d,26);float step=Mathf.Min(length-d,(phase<16?16:26)-phase);step=Mathf.Max(.001f,step);if(phase<16)RoutePaint.Add(new PaintedSegment{a=Vector3.Lerp(a,b,d/length),b=Vector3.Lerp(a,b,Mathf.Min(length,d+step)/length),color=color,passenger=true});d+=step;}}traveled+=length;}}

 public void RefreshRoutePaint(bool force=false){if(session==null||session.jobs==null||!force&&Time.unscaledTime<nextPaint)return;nextPaint=Time.unscaledTime+1;var jobs=session.jobs;if(selectedOffer!=null&&(jobs.Active||SelectedOffer<0||SelectedOffer>=jobs.offers.Length||jobs.offers[SelectedOffer]!=selectedOffer)){if(!jobs.Active)acceptFeedback="호출이 갱신됐습니다 · 목록에서 다시 선택하세요";selectedOffer=null;SelectedOffer=-1;}RoutePaint.Clear();
  if(IsOpen&&selectedPlace!=null){PaintPath(previewPath,false);return;}
  if(!jobs.Active&&selectedOffer!=null){PaintPath(pickupPath,false);PaintPath(previewPath,true);return;}
  PaintPath(jobs.nav.path,jobs.trip.State==TripState.OnTrip);
  if(jobs.trip.State==TripState.ToPickup&&jobs.current!=null){if(cachedRide!=jobs.current){cachedRide=jobs.current;ridePath=jobs.nav.Find(jobs.stops[jobs.current.pickup],jobs.stops[jobs.current.drop]);}PaintPath(ridePath,true);}else cachedRide=null;
 }

 public string ApproachSummary {get{var jobs=session.jobs;var p=jobs.Active?jobs.nav.path:pickupPath;float d=0;for(int i=1;i<p.Count;i++)d+=Vector3.Distance(p[i-1],p[i]);return p.Count<2?"승차 경로를 찾지 못했습니다":"내 차 → 승차 · "+d.ToString("0")+"m · 하늘색 실선";}}
 void DrawSidebar(float x,float w,Rect viewport){var jobs=session.jobs;GUI.Label(new Rect(x,90,w,34),session.simulationMatch?"공용 호출 · 최대 8개":"주변 호출 보기 (M)",heading);float top=132;
  string demand=session.simulationMatch?"4대가 함께 선택하는 호출입니다.\n먼저 수락한 차량이 운송합니다.":PassengerDemandPolicy.Description(session.business.ledger.Elapsed);float demandHeight=text.CalcHeight(new GUIContent(demand),w);GUI.Label(new Rect(x,top,w,demandHeight),demand,text);top+=demandHeight+8;
  if(selectedPlace!=null){float nameHeight=text.CalcHeight(new GUIContent(selectedPlace.name),w-16);float height=nameHeight+100;KoreanText.Panel(new Rect(x,top,w,height));GUI.Label(new Rect(x+8,top+8,w-16,nameHeight),selectedPlace.name,text);float length=0;for(int i=1;i<previewPath.Count;i++)length+=Vector3.Distance(previewPath[i-1],previewPath[i]);GUI.Label(new Rect(x+8,top+nameHeight+14,w-16,30),previewPath.Count<2?"연결 경로 없음 · 차로/출구로 이동하세요":"입구까지 약 "+length.ToString("0")+"m",new GUIStyle(text){fontSize=14});bool restore=jobs.Active&&!SelectedPickupFuel;GUI.enabled=!locationOpen&&(restore||!previousPause&&previewPath.Count>1);if(GUI.Button(new Rect(x+8,top+height-48,w-16,40),restore?"운송 경로로 돌아가기":SelectedPickupFuel?"호출 유지 · 주유소 길안내":"시설 길안내 시작",button)){if(restore)RestoreTripRoute();else StartPlaceGuidance();}GUI.enabled=!locationOpen;top+=height+12;}
  else {GUI.Label(new Rect(x,top,w,50),selectedOffer!=null||jobs.trip.State==TripState.ToPickup?ApproachSummary:"번호를 선택하면 승차·운송 경로를 표시합니다",text);top+=54;}
  GUI.Label(new Rect(x,top,w,28),"호출 목록 · 점선은 승객 운송 경로",new GUIStyle(text){font=KoreanText.BoldFont,fontSize=14});top+=32;
  float listHeight=Mathf.Max(72,viewport.yMax-top-154),rw=w-24;float content=0;var rows=new System.Collections.Generic.List<string>();var indices=new System.Collections.Generic.List<int>();var heights=new System.Collections.Generic.List<float>();
  if(!jobs.Active)for(int i=0;i<jobs.offers.Length;i++){var o=jobs.offers[i];if(o==null)continue;var caption=(i+1)+"  "+KoreanText.Stop(jobs.stops[o.pickup].name)+"\n→ "+KoreanText.Stop(jobs.stops[o.drop].name)+"\n예상 운임 "+PassengerReward.AdjustedFare(o.fare,session.law.ledger.TotalScore).ToString("N0")+"원";float height=Mathf.Max(84,button.CalcHeight(new GUIContent(caption),rw-20)+24);rows.Add(caption);indices.Add(i);heights.Add(height);content+=height+10;}
  var chosen=jobs.Active?jobs.current:selectedOffer;float foot=content;if(chosen!=null)content+=100;if(jobs.Active)content+=jobs.PassengerViaPending?94:44;
  filterScroll=GUI.BeginScrollView(new Rect(x,top,w,listHeight),filterScroll,new Rect(0,0,w-20,Mathf.Max(listHeight,content)));float y=0;
  for(int k=0;k<rows.Count;k++){int index=indices[k];var old=GUI.backgroundColor;if(index==SelectedOffer)GUI.backgroundColor=new Color(.35f,1,.8f);if(GUI.Button(new Rect(0,y,rw,heights[k]),rows[k],new GUIStyle(button){alignment=TextAnchor.MiddleLeft,padding=new RectOffset(10,10,4,4)}))SelectOffer(index);GUI.backgroundColor=old;y+=heights[k]+10;}
  if(chosen!=null){if(GUI.Button(new Rect(0,foot,rw,42),"승차 · "+KoreanText.Stop(jobs.stops[chosen.pickup].name),button))FocusStop(chosen.pickup);if(GUI.Button(new Rect(0,foot+50,rw,42),"하차 · "+KoreanText.Stop(jobs.stops[chosen.drop].name),button))FocusStop(chosen.drop);}
  if(jobs.Active){if(jobs.PassengerViaPending&&GUI.Button(new Rect(0,foot+100,rw,42),"경유 · "+KoreanText.Stop(jobs.stops[jobs.PassengerViaStop].name),button))FocusStop(jobs.PassengerViaStop);GUI.Label(new Rect(0,foot+(jobs.PassengerViaPending?150:100),rw,44),"운송 중 · 신규 호출은 운송 완료 후",text);}GUI.EndScrollView();
  string reason=AcceptBlockedReason;string status=!string.IsNullOrEmpty(acceptFeedback)?acceptFeedback:!string.IsNullOrEmpty(reason)?reason:"선택 "+(SelectedOffer+1)+" · "+KoreanText.Stop(jobs.stops[selectedOffer.pickup].name)+"\n→ "+KoreanText.Stop(jobs.stops[selectedOffer.drop].name);
  KoreanText.Panel(new Rect(x,viewport.yMax-150,w,94));GUI.Label(new Rect(x+8,viewport.yMax-147,w-16,88),status,new GUIStyle(text){fontSize=14,normal={textColor=string.IsNullOrEmpty(reason)?Color.white:new Color(1,.78f,.4f)}});
  // Keep a blocked action clickable so its rejection is visible instead of silently disabled.
  GUI.enabled=!locationOpen;if(GUI.Button(AcceptButtonBounds,string.IsNullOrEmpty(reason)?"선택한 호출 수락":"호출 수락 · 이용 조건 확인",button)){AcceptButtonClickCount++;AcceptSelected();}GUI.enabled=true;
 }
}
